actions.script:
const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.delete#Voicemail').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize(out.deleted ? 'Voicemail deleted' : 'Voicemail moved to the Trash'), 'success')

const list = calleeUserIdList ? (Array.isArray(calleeUserIdList) ? calleeUserIdList : String(calleeUserIdList).split(',')) : []
const out = ec.service.sync().name('org.moqui.impl.CallServices.start#Call').parameters({calleeUserIdList: list,
    video: String(video) !== 'N'}).requireNewTransaction(true).disableAuthz().call() || {}
newCallSessionId = out.callSessionId || null

const out = ec.service.sync().name('org.moqui.impl.VoiceServices.place#PhoneCall').parameters({phoneNumber: phoneNumber || '',
    fromNumber: fromNumber || null}).requireNewTransaction(true).disableAuthz().call() || {}
newCallSessionId = out.callSessionId || null

const room = chatRoomId && String(isRoomCall) === 'true' ? chatRoomId : null
const out = ec.service.sync().name('org.moqui.impl.CallServices.start#Call').parameters({chatRoomId: room,
    calleeUserIdList: room ? null : String(otherUserIds || '').split(',').filter((id) => id),
    video: String(video) !== 'false'}).requireNewTransaction(true).disableAuthz().call() || {}
newCallSessionId = out.callSessionId || null

const out = ec.service.sync().name('org.moqui.impl.CallServices.create#CallLink').parameters({name: name || '',
    policy: policy === 'link' ? 'link' : 'lobby', video: video !== 'N', expiryHours: Math.max(1, Number(expiryDays) || 7) * 24})
    .requireNewTransaction(true).disableAuthz().call() || {}
if (out.path) ec.message.addMessage(ec.resource.expand('Call link made: ${url} (copy it now: it is shown only this once)', '',
    {url: ec.web.getWebappRootUrl('webroot', null, true, false) + out.path}), 'success')

const out = ec.service.sync().name('org.moqui.impl.CallServices.open#CallLink').parameter('callLinkId', callLinkId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
newCallSessionId = out.callSessionId || null

const L = (text) => ec.l10n.localize(text)
const caps = ec.service.sync().name('org.moqui.impl.CallServices.get#Capabilities').requireNewTransaction(true).disableAuthz().call() || {}
callsActive = !!caps.active
callsReason = caps.active ? '' : caps.reasonCode === 'notBuilt' ? L('Calls are not built into this server.')
    : L('Calls are not available: no media server is running. An administrator sets rtc_media_port to start one.')
const when = (millis) => millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm a') : ''
const active = ec.service.sync().name('org.moqui.impl.CallServices.find#ActiveCalls').requireNewTransaction(true).disableAuthz().call() || {}
callList = Array.from(active.callList || []).map((call) => {
    const others = Array.from(call.participants || []).filter((p) => p.userId !== ec.user.userId).map((p) => p.displayName)
    return {callSessionId: call.callSessionId, who: others.join(', ') || L('Just you'),
        stateText: call.myLegStatus === 'offered' ? L('Ringing') : L('In the call'),
        kindText: call.video ? L('Video') : L('Audio'), startedText: when(call.startedDate),
        ringing: call.myLegStatus === 'offered'}
})
newCall = {calleeUserIdList: [], video: 'Y'}
// Call a number (V1): the user's caller IDs; the full dialer is V3
const voice = ec.service.sync().name('org.moqui.impl.VoiceServices.get#VoiceCapabilities').requireNewTransaction(true).disableAuthz().call() || {}
const myIds = ec.service.sync().name('org.moqui.impl.VoiceServices.find#MyCallerIds').requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
callerIdOptions = Array.from(myIds.numberList || []).map((n) => ({key: n.phoneNumber, text: n.phoneNumber + (n.description ? ' · ' + n.description : '')}))
phoneActive = !!voice.active
phoneReason = !voice.active ? L('Phone calls are not available here.') : !callerIdOptions.length ? L('You have no number to call from; an administrator can give you one.') : ''
newPhoneCall = {phoneNumber: '', fromNumber: callerIdOptions.length ? callerIdOptions[0].key : ''}

// the history, by outcome; the Missed tab marks them seen
const OUTCOMES = {placed: L('Placed'), answered: L('Answered'), missed: L('Missed'), declined: L('Declined'), ringing: L('Ringing')}
shownOutcome = ['missed', 'placed', 'answered', 'voicemail'].includes(outcome) ? outcome : ''
// voicemail (V2): the tab's unheard count, and its list when it is the tab shown
const unheardOut = ec.service.sync().name('org.moqui.impl.VoicemailServices.count#UnheardVoicemails').requireNewTransaction(true).disableAuthz().call() || {}
voicemailText = unheardOut.unheardCount ? L('Voicemail') + ' (' + unheardOut.unheardCount + ')' : L('Voicemail')
shownFolder = folder === 'trash' ? 'trash' : 'inbox'
shownHeard = ['heard', 'unheard'].includes(heard) ? heard : ''
voicemailList = []
trashCount = 0
if (shownOutcome === 'voicemail') {
    const vm = ec.service.sync().name('org.moqui.impl.VoicemailServices.find#Voicemails').parameters({folder: shownFolder,
        heard: shownHeard || null, pageIndex: Math.max(Number(pageIndex) || 0, 0), pageSize: 25}).requireNewTransaction(true).disableAuthz().call() || {}
    ec.message.clearErrors()
    trashCount = Number(vm.trashCount || 0)
    const seconds = (millis) => { const s = Math.round(Number(millis || 0) / 1000); return s < 60 ? s + ' s' : Math.floor(s / 60) + ' min ' + (s % 60) + ' s' }
    const TRANSCRIPTS = {pending: L('Transcribing'), done: '', failed: L('Transcript failed')}
    voicemailList = Array.from(vm.voicemailList || []).map((v) => ({voicemailId: v.voicemailId, fromName: v.fromName,
        fromNumber: v.fromNumber && v.fromNumber !== v.fromName ? v.fromNumber : '', whenText: when(v.receivedDate),
        lengthText: seconds(v.durationMs), stateText: v.heard ? L('Heard') : L('New'), heard: !!v.heard,
        note: v.status === 'audioFailed' ? L('The audio was not stored') : (v.transcriptSnippet || TRANSCRIPTS[v.transcriptStatus] || ''),
        inTrash: shownFolder === 'trash'}))
}
if (shownOutcome === 'missed') ec.service.sync().name('org.moqui.impl.CallServices.mark#MissedSeen').requireNewTransaction(true).disableAuthz().call()
const missedOut = ec.service.sync().name('org.moqui.impl.CallServices.count#MissedCalls').requireNewTransaction(true).disableAuthz().call() || {}
missedText = missedOut.missedCount ? L('Missed') + ' (' + missedOut.missedCount + ')' : L('Missed')
historyPage = Math.max(Number(pageIndex) || 0, 0)
const found = shownOutcome === 'voicemail' ? {} : ec.service.sync().name('org.moqui.impl.CallServices.find#Calls').parameters({outcome: shownOutcome || null,
    pageIndex: historyPage, pageSize: 25}).requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
const minutes = (seconds) => !seconds ? '' : seconds < 60 ? seconds + ' s' : Math.floor(seconds / 60) + ' min ' + (seconds % 60) + ' s'
historyList = Array.from(found.callList || []).map((row) => ({callSessionId: row.callSessionId,
    who: row.otherNames.join(', ') || L('Just you'), outcomeText: OUTCOMES[row.outcome] || row.outcome,
    outcomeIcon: row.outcome === 'missed' ? 'sym_o_phone_missed' : row.role === 'caller' ? 'sym_o_call_made' : 'sym_o_call_received',
    kindText: row.video ? L('Video') : L('Audio'), whenText: when(row.startedDate), lengthText: minutes(row.durationSeconds),
    otherUserIds: Array.from(row.otherUserIdList || []).join(','), chatRoomId: row.chatRoomId, isRoomCall: row.kind === 'group' ? 'true' : 'false',
    video: row.video ? 'true' : 'false', canCallBack: callsActive && row.status === 'ended' && (row.otherUserIdList.length > 0 || row.kind === 'group'),
    unseen: !!row.unseen}))
historyCount = Number(found.callListCount || 0)

// the call links that still work, and the meetings of the next week from the apps' providers
const links = ec.service.sync().name('org.moqui.impl.CallServices.find#CallLinks').requireNewTransaction(true).disableAuthz().call() || {}
linkList = Array.from(links.linkList || []).map((link) => ({callLinkId: link.callLinkId, name: link.name,
    policyText: link.policy === 'link' ? L('Straight in') : L('Lobby'), kindText: link.video ? L('Video') : L('Audio'),
    expiryText: when(link.expiryDate), stateText: link.callSessionId ? (link.waitingCount ? ec.resource.expand('In progress, ${n} waiting', '',
        {n: link.waitingCount}) : L('In progress')) : (link.lastUsedDate ? L('Used') + ' ' + when(link.lastUsedDate) : L('Not used yet'))}))
newLink = {name: '', policy: 'lobby', video: 'Y', expiryDays: '7'}
const nowMillis = Number(ec.user.nowTimestamp)
const meetings = ec.service.sync().name('org.moqui.impl.ShellServices.call#Providers').parameters({hook: 'meetings-source',
    parameters: {fromDate: new Date(nowMillis), thruDate: new Date(nowMillis + 7 * 86400000)}}).disableAuthz().call() || {}
ec.message.clearErrors()
meetingsAvailable = !meetings.unavailable
meetingList = []
for (const result of Array.from(meetings.results || [])) for (const meeting of Array.from(result.meetingList || []))
    meetingList.push({title: meeting.title || '', whenText: meeting.whenText || when(meeting.startDate), joinUrl: meeting.joinUrl || null,
        link: meeting.link || null, isNow: !!meeting.isNow})
meetingsFailed = Array.from(meetings.failedParts || []).length > 0
hasMore = (historyPage + 1) * 25 < historyCount
nextPage = historyPage + 1
